#!/usr/bin/env python3
"""Writes the gitignored MARQUEE/Services/Secrets.swift from the environment.

The TMDB read token comes from the TMDB_READ_TOKEN secret in CI. When it is
missing the file still compiles with an empty token, and the app shows its
friendly "add your TMDB key" state instead of failing.
"""
import json
import os
from pathlib import Path

token = os.environ.get("TMDB_READ_TOKEN", "").strip()
path = Path(__file__).resolve().parent.parent / "MARQUEE" / "Services" / "Secrets.swift"
path.write_text(
    "// Generated by tools/write_secrets.py. Do not edit or commit.\n"
    "enum Secrets {\n"
    f"    static let tmdbReadToken: String = {json.dumps(token)}\n"
    "}\n"
)
print("Secrets.swift written (" + ("token present" if token else "no token") + ")")
